import{_ as o,a0 as r,w as l,s as d,ao as s,I as a,x as n,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"實測 Linux Mint 升級工具 | LCTT x X-CMD","titleTemplate":false,"description":"實測 Linux Mint 升級工具 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"實測 Linux Mint 升級工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"實測 Linux Mint 升級工具 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220425 Linux Mint Upgrade Tool - Here-s How it Works","title":"實測 Linux Mint 升級工具","tag":"202205","desc":""},"relativePath":"202205/20220425 Linux Mint Upgrade Tool - Here-s How it Works.md","filePath":"[post].md"}'),u={name:"202205/20220425 Linux Mint Upgrade Tool - Here-s How it Works.md"};function g(m,t,x,w,h,b){const e=r("Link");return l(),d("div",null,[t[20]||(t[20]=s('<h1 id="實測-linux-mint-升級工具" tabindex="-1">實測 Linux Mint 升級工具 <a class="header-anchor" href="#實測-linux-mint-升級工具" aria-label="Permalink to “實測 Linux Mint 升級工具”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/01/170956n81yky0l8vbvy1n8.jpg" alt=""></p><blockquote><p>我們通過實際升級測試了 Linux Mint 升級工具（mintupgrade GUI）。這是我們的發現。</p></blockquote><p>這個工具正在開發中，可能包含錯誤，除非你想實驗一下，否則請不要在你的日常中使用它。</p><h3 id="linux-mint-升級工具" tabindex="-1">Linux Mint 升級工具 <a class="header-anchor" href="#linux-mint-升級工具" aria-label="Permalink to “Linux Mint 升級工具”">​</a></h3>',5)),a("p",null,[t[1]||(t[1]=n("Linux Mint 團隊 ",-1)),i(e,{href:"https://www.debugpoint.com/2022/04/linux-mint-21-announcement/"},{default:p(()=>[...t[0]||(t[0]=[n("宣佈",-1)])]),_:1}),t[2]||(t[2]=n("，他們建立了一個新的工具來升級 Linux Mint 的主要版本。它被稱為 “mintupgrade2”。它目前正在開發中，計劃用於升級主要版本。例如，從 Linux Mint 20 到 21，而不是小版本的升級。",-1))]),t[21]||(t[21]=s(`<p>雖然你可以使用標準的 <code>apt</code> 命令來升級版本，然而，Mint 團隊認為主要版本的升級是很棘手的。新用户很難順利升級，因為它涉及到終端和一套複雜的命令步驟。</p><p>此外，這個圖形用户界面是對 mintupgrade 程序的封裝，並帶有一些附加功能，它帶來了一套系統前檢查和一鍵修復的升級過程。</p><p>除此之外，mintupgrade 還會檢查你是否連接到電源、系統是否是最新的、磁盤空間的可用性等等。</p><p>為了讓大家瞭解它的外觀和工作情況，我們使用 LMDE 4 設置了一個測試平台做了個測試。</p><p>但在這之前，讓我快速介紹一下它的功能：</p><ul><li>完全由 GUI 驅動的升級過程</li><li>多語言支持</li><li>升級前檢查：系統備份、電源、磁盤空間、刪除的軟件包列表</li><li>可配置</li><li>提醒你來自上一個版本的孤兒軟件包</li><li>給你修復問題的選項</li></ul><h3 id="它是如何工作的" tabindex="-1">它是如何工作的 <a class="header-anchor" href="#它是如何工作的" aria-label="Permalink to “它是如何工作的”">​</a></h3><p>當我們通過命令 <code>mintupgrade</code> 運行這個 Mint 升級工具時，這個圖形用户界面程序友好的歡迎屏幕是一個很好的起點，它開啓了升級過程，然後它自己開始進行一系列的檢查。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Starting-the-upgrade-process.jpg" alt="Starting the upgrade process"></p><p>除此之外，當它在你的系統中發現一些問題時，它會停下來並給你足夠的細節。當你點擊“修復”後，它就可以再次恢復進程。</p><p>不止如此。如果由於網絡或互聯網或任何其他問題而中斷，它也可以恢復升級過程。</p><p>在我們的測試過程中，該工具在我們的測試系統中發現了以下錯誤，只需點擊一下就能修復它們。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Apt-Cache-check-1024x521.jpg" alt="Apt Cache check"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Mint-Upgrade-detects-that-system-snapshots-not-present-1024x522.jpg" alt="Mint Upgrade detects that system snapshots are not present"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Check-for-Orphan-Packages-1024x522.jpg" alt="Check for Orphan Packages"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Status-before-upgrade-1024x528.jpg" alt="Status before upgrade"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Mint-Upgrade-can-detect-the-packages-require-downgrade-1024x612.jpg" alt="Mint Upgrade can detect the packages that require a downgrade"></p><p>最後，我們成功地將一個測試系統從 LMDE 4 升級到 LMDE 5。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Upgrade-Complete-1024x612.jpg" alt="Upgrade Complete"></p><h4 id="如何獲得這個升級工具" tabindex="-1">如何獲得這個升級工具 <a class="header-anchor" href="#如何獲得這個升級工具" aria-label="Permalink to “如何獲得這個升級工具”">​</a></h4><p>使用下面的命令，該工具的安裝很簡單。但正如該團隊所建議的，它現在處於 BETA 狀態，所以不要用它來進行正式場合的升級。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install mintupgrade</span></span></code></pre></div><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>最後，我認為這是 Linux Mint 團隊的最好的工具之一。正如你在上面看到的，它自己處理了許多錯誤。我所做的只是點擊“修復”按鈕。而這個工具足夠聰明，能夠理解所有的故障點，並負責補救。</p>`,24)),a("p",null,[i(e,{href:"https://github.com/linuxmint/mintupgrade"},{default:p(()=>[...t[3]||(t[3]=[n("mintupgrade 工具",-1)])]),_:1}),t[4]||(t[4]=n(" 將在 Linux Mint 21 “Vanessa” 發佈前發佈，大約在 2022 年第三季度末或第四季度初。",-1))]),t[22]||(t[22]=a("hr",null,null,-1)),a("p",null,[t[6]||(t[6]=n("via: ",-1)),i(e,{href:"https://www.debugpoint.com/2022/04/mint-upgrade-tool/"},{default:p(()=>[...t[5]||(t[5]=[n("https://www.debugpoint.com/2022/04/mint-upgrade-tool/",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=n("作者：",-1)),i(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...t[7]||(t[7]=[n("Arindam",-1)])]),_:1}),t[12]||(t[12]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[8]||(t[8]=[n("lujun9972",-1)])]),_:1}),t[13]||(t[13]=n(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...t[9]||(t[9]=[n("geekpi",-1)])]),_:1}),t[14]||(t[14]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[n("LCTT",-1)])]),_:1}),t[18]||(t[18]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[n("Linux中國",-1)])]),_:1}),t[19]||(t[19]=n(" 榮譽推出",-1))])])}const L=o(u,[["render",g]]);export{T as __pageData,L as default};
